     "type": "string"
    },
    "instructions": {
     "description": "What to pick between and how to judge. The answer is the most likely label plus the full probability distribution; it collapses to the label under the question name.",
     "title": "Instructions",
     "type": "string"
    },
    "criteria": {
     "additionalProperties": {
      "anyOf": [
       {
        "type": "string"
       },
       {
        "type": "null"
       }
      ]
     },
     "description": "Label to description. Null when the label is self-explanatory. Router branches keyed on this question use these labels.",
     "minProperties": 2,
     "title": "Criteria",
     "type": "object"
    }
   },
   "required": [
    "type",
    "instructions",
    "criteria"
   ],
   "title": "ChoiceQuestion",
   "type": "object"
  },
  "ClientTaskStep": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "Short kebab-case identifier, unique within the procedure. Edges (`inputs_to`, router `branches`) reference steps by this name.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Name",
     "type": "string"
    },
    "kind": {
     "const": "client_task",
     "description": "The client performs the work itself: generation, synthesis, reasoning.",
     "title": "Kind",
     "type": "string"
    },
    "description": {
     "description": "What the client is asked to do. One line; the template carries the detail.",
     "title": "Description",
     "type": "string"
    },
    "inputs": {
     "description": "The keys this step reads from the state; every listed name is required. Each must be produced by a step on every path to this one, or declared on the start step, whose inputs are what the client supplies.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Inputs",
     "type": "array"
    },
    "template": {
     "description": "The task template, rendered with `{key}` placeholders from the input, `{assets[name]}` for injected assets, and `{meta.name}` for the skill name. The client performs the task and answers with structured JSON matching the step's `outputs`.",
     "pattern": "^assets/.+",
     "title": "Template",
     "type": "string"
    },
    "outputs": {
     "description": "The keys the client's answer adds to the state. Required: they are what the client is asked to answer with.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Outputs",
     "type": "array"
    },
    "assets": {
     "description": "Extra assets available to the template as `{assets[name]}`, where name is the file stem.",
     "items": {
      "description": "Path under `assets/`, relative to the skill folder. Assets are eager: their content is injected on every invoke.",
      "pattern": "^assets/.+",
      "type": "string"
     },
     "title": "Assets",
     "type": "array"
    },
    "references": {
     "description": "Documents the client may load on demand while doing the task.",
     "items": {
      "$ref": "#/$defs/Reference"
     },
     "title": "References",
     "type": "array"
    },
    "framing": {
     "default": true,
     "description": "Prepend the AIP system framing (which workflow this is, how to read the state) to the rendered task.",
     "title": "Framing",
     "type": "boolean"
    },
    "inputs_to": {
     "description": "The step that receives this step's output.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Inputs To",
     "type": "string"
    }
   },
   "required": [
    "name",
    "kind",
    "description",
    "inputs",
    "template",
    "inputs_to"
   ],
   "title": "ClientTaskStep",
   "type": "object"
  },
  "DataType": {
   "description": "AIP type vocabulary. Machine-enforced at runtime: the server compiles each step's\n`inputs` and `outputs` to JSON Schemas and validates the state and the step's result against them.",
   "enum": [
    "string",
    "integer",
    "float",
    "boolean",
    "object",
    "list[*]"
   ],
   "title": "DataType",
   "type": "string"
  },
  "DecisionStep": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "Short kebab-case identifier, unique within the procedure. Edges (`inputs_to`, router `branches`) reference steps by this name.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Name",
     "type": "string"
    },
    "kind": {
     "const": "decision",
     "description": "A structured decision model answers typed questions about the input.",
     "title": "Kind",
     "type": "string"
    },
    "description": {
     "description": "What this decision settles. One line.",
     "title": "Description",
     "type": "string"
    },
    "inputs": {
     "description": "The keys this step reads from the state; every listed name is required. Each must be produced by a step on every path to this one, or declared on the start step, whose inputs are what the client supplies.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Inputs",
     "type": "array"
    },
    "questions": {
     "description": "Questions keyed by name. Answers come back under the same names and, once collapsed, become keys in the state: a decision's outputs are its question names.",
     "minProperties": 1,
     "patternProperties": {
      "^[A-Za-z_][A-Za-z0-9_]*$": {
       "description": "One SystemOne question. `instructions` carry the evaluation criteria; the step's input is the content being evaluated. Passed through to the decision model as-is.",
       "discriminator": {
        "mapping": {
         "choice": "#/$defs/ChoiceQuestion",
         "noul": "#/$defs/NoulQuestion",
         "score": "#/$defs/ScoreQuestion"
        },
        "propertyName": "type"
       },
       "oneOf": [
        {
         "$ref": "#/$defs/NoulQuestion"
        },
        {
         "$ref": "#/$defs/ChoiceQuestion"
        },
        {
         "$ref": "#/$defs/ScoreQuestion"
        }
       ]
      }
     },
     "title": "Questions",
     "type": "object"
    },
    "thresholds": {
     "additionalProperties": {
      "maximum": 1,
      "minimum": 0,
      "type": "number"
     },
     "description": "Per-question review thresholds, keyed by question name. For `noul`: flag when the probability is within this margin of 0.5. For `choice` and `score`: flag when the model's confidence is below this value. The client may override per call; it makes the final call on flagged answers.",
     "title": "Thresholds",
     "type": "object"
    },
    "history": {
     "default": false,
     "description": "Send the run's history (every earlier step's input and result) to the decision model alongside the declared inputs. Off by default: history grows with the run and is billed on every decision.",
     "title": "History",
     "type": "boolean"
    },
    "inputs_to": {
     "description": "The step that receives this step's output.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Inputs To",
     "type": "string"
    }
   },
   "required": [
    "name",
    "kind",
    "description",
    "inputs",
    "questions",
    "inputs_to"
   ],
   "title": "DecisionStep",
   "type": "object"
  },
  "EndStep": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "Short kebab-case identifier, unique within the procedure. Edges (`inputs_to`, router `branches`) reference steps by this name.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Name",
     "type": "string"
    },
    "kind": {
     "const": "end",
     "description": "Terminal node.",
     "title": "Kind",
     "type": "string"
    },
    "description": {
     "anyOf": [
      {
       "type": "string"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "description": "What the final state represents. One line.",
     "title": "Description"
    },
    "inputs": {
     "description": "The procedure's result: the keys handed back to the client when the run is done.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Inputs",
     "type": "array"
    }
   },
   "required": [
    "name",
    "kind",
    "inputs"
   ],
   "title": "EndStep",
   "type": "object"
  },
  "ExecutionStep": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "Short kebab-case identifier, unique within the procedure. Edges (`inputs_to`, router `branches`) reference steps by this name.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Name",
     "type": "string"
    },
    "kind": {
     "const": "execution",
     "description": "A script runs. Analogous to a tool call.",
     "title": "Kind",
     "type": "string"
    },
    "description": {
     "description": "What the script does. One line; the script is the source of truth.",
     "title": "Description",
     "type": "string"
    },
    "inputs": {
     "description": "The keys this step reads from the state; every listed name is required. Each must be produced by a step on every path to this one, or declared on the start step, whose inputs are what the client supplies.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Inputs",
     "type": "array"
    },
    "script": {
     "description": "Path under `scripts/`, relative to the skill folder. Receives one JSON object on stdin ({state, assets, expects}, where `state` holds only the step's declared `inputs`) and writes one JSON object to stdout holding exactly the step's `outputs`.",
     "pattern": "^scripts/.+",
     "title": "Script",
     "type": "string"
    },
    "outputs": {
     "description": "The keys this step adds to the state. Each key has exactly one producer in the procedure and is never a start input, so the state only grows and nothing is overwritten.",
     "items": {
      "$ref": "#/$defs/IOItem"
     },
     "title": "Outputs",
     "type": "array"
    },
    "command": {
     "anyOf": [
      {
       "items": {
        "minLength": 1,
        "type": "string"
       },
       "minItems": 1,
       "type": "array"
      },
      {
       "type": "null"
      }
     ],
     "default": null,
     "description": "How the script is launched, as an argument list run from the script's folder: `[\"bash\", \"run.sh\"]`. Omitted, it is `python` on the script. The first item must be the `requires` interpreter or one of its `tools`.",
     "title": "Command"
    },
    "assets": {
     "description": "Constant inputs the script always receives, such as a config file. Re-read from disk on every invoke.",
