def process_placeholders(root, data, key_map, filled, missing):
    for p in list(root.iter(W_P)):
        text = ptext(p)
        matches = list(PLACEHOLDER_RE.finditer(text))
        for m in reversed(matches):  # right-to-left keeps earlier offsets valid
