    parent = p.getparent()
    if parent is None:
        return
    # a table cell / text box must keep at least one paragraph
    if parent.tag in (qn("w:tc"), qn("w:txbxContent")) and len(parent.findall(W_P)) <= 1:
        for t in own_texts(p):
            t.text = ""
        return
    parent.remove(p)


