    roots = [doc.element.body]
    seen = set()
    for rel in doc.part.rels.values():
        if rel.is_external:
            continue
        part = rel.target_part
        name = str(part.partname)
        if re.search(r"/word/(header|footer)\d*\.xml$", name) and name not in seen:
            seen.add(name)
            roots.append(part.element)
