        same = end_re.search(ptext(p), m.end())
        if same:
            if include:
                splice(p, same.start(), same.end(), "")
                splice(p, m.start(), m.end(), "")
            else:
                splice(p, m.start(), same.end(), "")
            if not ptext(p).strip():
                remove_paragraph(p)
            continue
