    if left:
        issues.append("output still contains template markup: " + ", ".join(left))
    return {
        "output_file": output_path,
        "filled_placeholders": filled,
        "conditionals": conditionals,
        "issues": issues,
        "status": "needs_attention" if issues else "complete",
    }


